import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Button, Table, Form, Modal } from 'react-bootstrap';
import { apiService } from '../services/api';
import { useAuth } from '../contexts/AuthContext';
import LoadingSpinner from '../components/LoadingSpinner';
import Toast from '../components/Toast';

interface TransferItem {
  date_acquired: string;
  item_no: string;
  ics_no: string;
  description: string;
  amount: number;
  condition: string;
}

interface InventoryTransfer {
  id?: string;
  itr_no: string;
  entity_name: string;
  fund_cluster: string;
  transfer_type: 'Donation' | 'Reassignment' | 'Relocate' | 'Others';
  transfer_type_others?: string;
  items: TransferItem[];
  reason_for_transfer: string;
  approved_by: string;
  released_issued_by: string;
  received_by: string;
  date: string;
  status: 'Draft' | 'Submitted';
}

const InventoryTransferReport: React.FC = () => {
  const { user } = useAuth();
  const [transfers, setTransfers] = useState<InventoryTransfer[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [toastMessage, setToastMessage] = useState('');
  const [toastType, setToastType] = useState<'success' | 'error' | 'warning' | 'info'>('info');
  const [showToast, setShowToast] = useState(false);

  const [currentTransfer, setCurrentTransfer] = useState<InventoryTransfer>({
    itr_no: '',
    entity_name: '',
    fund_cluster: '',
    transfer_type: 'Reassignment',
    transfer_type_others: '',
    items: [],
    reason_for_transfer: '',
    approved_by: '',
    released_issued_by: user?.full_name || '',
    received_by: '',
    date: new Date().toISOString().split('T')[0],
    status: 'Draft'
  });

  const [newItem, setNewItem] = useState<TransferItem>({
    date_acquired: '',
    item_no: '',
    ics_no: '',
    description: '',
    amount: 0,
    condition: 'Good'
  });

  useEffect(() => {
    fetchTransfers();
  }, []);

  const fetchTransfers = async () => {
    try {
      setLoading(true);
      setError(null);
      
      // Fetch inventory transfer reports from API
      try {
        const response = await (window as any).fetch('/api/inventory-transfer-reports', {
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('authToken')}`
          }
        });
        
        if (response.ok) {
          const data = await response.json();
          setTransfers(data || []);
        } else {
          setTransfers([]);
        }
      } catch (err) {
        console.error('API call error:', err);
        setTransfers([]);
      }
    } catch (err) {
      setError('Failed to load inventory transfer reports');
      console.error(err);
      setTransfers([]);
    } finally {
      setLoading(false);
    }
  };

  const handleAddItem = () => {
    if (!newItem.date_acquired || !newItem.item_no || !newItem.description) {
      setToastMessage('Please fill in required item fields');
      setToastType('warning');
      setShowToast(true);
      return;
    }

    setCurrentTransfer({
      ...currentTransfer,
      items: [...currentTransfer.items, newItem]
    });

    setNewItem({
      date_acquired: '',
      item_no: '',
      ics_no: '',
      description: '',
      amount: 0,
      condition: 'Good'
    });
  };

  const handleRemoveItem = (index: number) => {
    setCurrentTransfer({
      ...currentTransfer,
      items: currentTransfer.items.filter((_, i) => i !== index)
    });
  };

  const handleSubmit = async () => {
    try {
      if (!currentTransfer.entity_name || currentTransfer.items.length === 0) {
        setToastMessage('Please fill in all required fields and add at least one item');
        setToastType('warning');
        setShowToast(true);
        return;
      }

      // Auto-generate ITR No. if not provided
      const itrNo = currentTransfer.itr_no || `ITR-${new Date().getFullYear()}-${String(transfers.length + 1).padStart(4, '0')}`;

      const transferData = {
        ...currentTransfer,
        itr_no: itrNo
      };

      // Submit to API
      const response = await fetch('/api/inventory-transfer-reports', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('authToken')}`
        },
        body: JSON.stringify(transferData)
      });

      if (response.ok) {
        setToastMessage('Inventory Transfer Report created successfully');
        setToastType('success');
        setShowToast(true);
        setShowModal(false);
        
        // Reset form
        setCurrentTransfer({
          itr_no: '',
          entity_name: '',
          fund_cluster: '',
          transfer_type: 'Reassignment',
          transfer_type_others: '',
          items: [],
          reason_for_transfer: '',
          approved_by: '',
          released_issued_by: user?.full_name || '',
          received_by: '',
          date: new Date().toISOString().split('T')[0],
          status: 'Draft'
        });
        
        // Refresh the list
        fetchTransfers();
      } else {
        const errorData = await response.json();
        setToastMessage(errorData.detail || 'Failed to create transfer report');
        setToastType('error');
        setShowToast(true);
      }
    } catch (err) {
      console.error('Error submitting transfer:', err);
      setToastMessage('Error creating inventory transfer report');
      setToastType('error');
      setShowToast(true);
    }
  };

  const filteredTransfers = transfers.filter((transfer: any) =>
    transfer.itr_no?.toString().toLowerCase().includes(searchTerm.toLowerCase()) ||
    transfer.entity_name?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return <LoadingSpinner size="lg" text="Loading inventory transfer reports..." />;
  }

  return (
    <Container fluid className="py-4">
      {error && <Toast message={error} type="error" show={!!error} onClose={() => setError(null)} />}

      <Row className="mb-4">
        <Col>
          <h1 className="mb-2">Inventory Transfer Report</h1>
          <p className="text-muted">Manage and track inventory transfers between custodians</p>
        </Col>
        <Col xs="auto">
          <Button 
            variant="primary" 
            onClick={() => setShowModal(true)}
            className="d-flex align-items-center gap-2"
          >
            <i className="bi bi-plus-lg"></i>
            New Transfer
          </Button>
        </Col>
      </Row>

      <Card>
        <Card.Body>
          <Form className="mb-4">
            <Form.Group>
              <Form.Control
                placeholder="Search by ITR No. or Entity Name..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="form-control-sm"
              />
            </Form.Group>
          </Form>

          {filteredTransfers.length > 0 ? (
            <Table striped bordered hover responsive>
              <thead>
                <tr>
                  <th>ITR No.</th>
                  <th>Entity Name</th>
                  <th>Transfer Type</th>
                  <th>Date</th>
                  <th>Items</th>
                  <th>Status</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredTransfers.map((transfer: any) => (
                  <tr key={transfer.id || transfer.itr_no}>
                    <td>{transfer.itr_no}</td>
                    <td>{transfer.entity_name}</td>
                    <td>{transfer.transfer_type}</td>
                    <td>{transfer.date}</td>
                    <td>{transfer.items?.length || 0}</td>
                    <td>
                      <span className={`badge bg-${transfer.status === 'Submitted' ? 'success' : 'warning'}`}>
                        {transfer.status}
                      </span>
                    </td>
                    <td>
                      <Button variant="info" size="sm">
                        <i className="bi bi-eye me-1"></i>
                        View
                      </Button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </Table>
          ) : (
            <div className="text-center py-5">
              <p className="text-muted">No inventory transfer reports found. Create a new one to get started.</p>
            </div>
          )}
        </Card.Body>
      </Card>

      {/* Create New Transfer Modal */}
      <Modal show={showModal} onHide={() => setShowModal(false)} size="lg" centered>
        <Modal.Header closeButton className="bg-primary text-white">
          <Modal.Title>
            <i className="bi bi-file-earmark-text me-2"></i>
            New Inventory Transfer Report
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form>
            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Entity Name *</Form.Label>
                  <Form.Control
                    type="text"
                    value={currentTransfer.entity_name}
                    onChange={(e) => setCurrentTransfer({ ...currentTransfer, entity_name: e.target.value })}
                    placeholder="e.g., CAVITE STATE UNIVERSITY"
                    required
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>ITR No.</Form.Label>
                  <Form.Control
                    type="text"
                    value={currentTransfer.itr_no}
                    onChange={(e) => setCurrentTransfer({ ...currentTransfer, itr_no: e.target.value })}
                    placeholder="Auto-generated if blank"
                  />
                </Form.Group>
              </Col>
            </Row>

            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Fund Cluster</Form.Label>
                  <Form.Control
                    type="text"
                    value={currentTransfer.fund_cluster}
                    onChange={(e) => setCurrentTransfer({ ...currentTransfer, fund_cluster: e.target.value })}
                    placeholder="Fund Cluster"
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Date *</Form.Label>
                  <Form.Control
                    type="date"
                    value={currentTransfer.date}
                    onChange={(e) => setCurrentTransfer({ ...currentTransfer, date: e.target.value })}
                    required
                  />
                </Form.Group>
              </Col>
            </Row>

            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Transfer Type *</Form.Label>
                  <Form.Select
                    value={currentTransfer.transfer_type}
                    onChange={(e) => setCurrentTransfer({ ...currentTransfer, transfer_type: e.target.value as any })}
                    required
                  >
                    <option value="Reassignment">Reassignment</option>
                    <option value="Donation">Donation</option>
                    <option value="Relocate">Relocate</option>
                    <option value="Others">Others (Specify)</option>
                  </Form.Select>
                </Form.Group>
              </Col>
              {currentTransfer.transfer_type === 'Others' && (
                <Col md={6}>
                  <Form.Group className="mb-3">
                    <Form.Label>Specify Other Type *</Form.Label>
                    <Form.Control
                      type="text"
                      value={currentTransfer.transfer_type_others || ''}
                      onChange={(e) => setCurrentTransfer({ ...currentTransfer, transfer_type_others: e.target.value })}
                      placeholder="Specify transfer type"
                      required
                    />
                  </Form.Group>
                </Col>
              )}
            </Row>

            <hr />
            <h6 className="fw-bold mb-3">Items to Transfer</h6>

            {/* Add Item Section */}
            <Card className="mb-3 bg-light">
              <Card.Body>
                <Row>
                  <Col md={3}>
                    <Form.Group className="mb-2">
                      <Form.Label className="small">Date Acquired *</Form.Label>
                      <Form.Control
                        type="date"
                        size="sm"
                        value={newItem.date_acquired}
                        onChange={(e) => setNewItem({ ...newItem, date_acquired: e.target.value })}
                      />
                    </Form.Group>
                  </Col>
                  <Col md={3}>
                    <Form.Group className="mb-2">
                      <Form.Label className="small">Item No. *</Form.Label>
                      <Form.Control
                        type="text"
                        size="sm"
                        value={newItem.item_no}
                        onChange={(e) => setNewItem({ ...newItem, item_no: e.target.value })}
                        placeholder="Item No."
                      />
                    </Form.Group>
                  </Col>
                  <Col md={3}>
                    <Form.Group className="mb-2">
                      <Form.Label className="small">ICS No./Date</Form.Label>
                      <Form.Control
                        type="text"
                        size="sm"
                        value={newItem.ics_no}
                        onChange={(e) => setNewItem({ ...newItem, ics_no: e.target.value })}
                        placeholder="ICS No."
                      />
                    </Form.Group>
                  </Col>
                  <Col md={3}>
                    <Form.Group className="mb-2">
                      <Form.Label className="small">Condition</Form.Label>
                      <Form.Select
                        size="sm"
                        value={newItem.condition}
                        onChange={(e) => setNewItem({ ...newItem, condition: e.target.value })}
                      >
                        <option value="Good">Good</option>
                        <option value="Fair">Fair</option>
                        <option value="Poor">Poor</option>
                        <option value="Damaged">Damaged</option>
                      </Form.Select>
                    </Form.Group>
                  </Col>
                </Row>
                <Row>
                  <Col md={7}>
                    <Form.Group className="mb-2">
                      <Form.Label className="small">Description *</Form.Label>
                      <Form.Control
                        type="text"
                        size="sm"
                        value={newItem.description}
                        onChange={(e) => setNewItem({ ...newItem, description: e.target.value })}
                        placeholder="Item Description"
                      />
                    </Form.Group>
                  </Col>
                  <Col md={3}>
                    <Form.Group className="mb-2">
                      <Form.Label className="small">Amount</Form.Label>
                      <Form.Control
                        type="number"
                        size="sm"
                        value={newItem.amount}
                        onChange={(e) => setNewItem({ ...newItem, amount: parseFloat(e.target.value) || 0 })}
                        placeholder="0.00"
                      />
                    </Form.Group>
                  </Col>
                  <Col md={2} className="d-flex align-items-end">
                    <Button variant="success" size="sm" onClick={handleAddItem} className="w-100">
                      <i className="bi bi-plus me-1"></i>
                      Add
                    </Button>
                  </Col>
                </Row>
              </Card.Body>
            </Card>

            {/* Items List */}
            {currentTransfer.items.length > 0 && (
              <div className="table-responsive mb-3">
                <Table bordered striped size="sm">
                  <thead className="bg-light">
                    <tr>
                      <th>Date Acquired</th>
                      <th>Item No.</th>
                      <th>ICS No.</th>
                      <th>Description</th>
                      <th>Amount</th>
                      <th>Condition</th>
                      <th>Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {currentTransfer.items.map((item, idx) => (
                      <tr key={idx}>
                        <td>{item.date_acquired}</td>
                        <td>{item.item_no}</td>
                        <td>{item.ics_no}</td>
                        <td>{item.description}</td>
                        <td>{item.amount}</td>
                        <td>{item.condition}</td>
                        <td>
                          <Button
                            variant="danger"
                            size="sm"
                            onClick={() => handleRemoveItem(idx)}
                          >
                            <i className="bi bi-trash"></i>
                          </Button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              </div>
            )}

            <hr />

            <Form.Group className="mb-3">
              <Form.Label>Reason for Transfer *</Form.Label>
              <Form.Control
                as="textarea"
                rows={2}
                value={currentTransfer.reason_for_transfer}
                onChange={(e) => setCurrentTransfer({ ...currentTransfer, reason_for_transfer: e.target.value })}
                placeholder="Reason for transfer"
              />
            </Form.Group>

            <Row>
              <Col md={4}>
                <Form.Group className="mb-3">
                  <Form.Label>Approved By</Form.Label>
                  <Form.Control
                    type="text"
                    value={currentTransfer.approved_by}
                    onChange={(e) => setCurrentTransfer({ ...currentTransfer, approved_by: e.target.value })}
                    placeholder="Name"
                  />
                </Form.Group>
              </Col>
              <Col md={4}>
                <Form.Group className="mb-3">
                  <Form.Label>Released/Issued By</Form.Label>
                  <Form.Control
                    type="text"
                    value={currentTransfer.released_issued_by}
                    onChange={(e) => setCurrentTransfer({ ...currentTransfer, released_issued_by: e.target.value })}
                    placeholder="Name"
                  />
                </Form.Group>
              </Col>
              <Col md={4}>
                <Form.Group className="mb-3">
                  <Form.Label>Received By</Form.Label>
                  <Form.Control
                    type="text"
                    value={currentTransfer.received_by}
                    onChange={(e) => setCurrentTransfer({ ...currentTransfer, received_by: e.target.value })}
                    placeholder="Name"
                  />
                </Form.Group>
              </Col>
            </Row>
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowModal(false)}>
            Cancel
          </Button>
          <Button variant="primary" onClick={handleSubmit}>
            <i className="bi bi-check-circle me-2"></i>
            Save Transfer Report
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Toast Notification */}
      <Toast
        show={showToast}
        message={toastMessage}
        type={toastType}
        onClose={() => setShowToast(false)}
      />
    </Container>
  );
};

export default InventoryTransferReport;
